<?php
namespace App\Controllers;
use App\Core\{Controller,Database,Request}; use App\Models\{Vendor,Product,Order,User};
class AdminController extends Controller { public function dashboard(){ $db=Database::pdo(); return $this->view('admin/dashboard',['sales'=>$db->query('select coalesce(sum(total),0) t from orders')->fetch()['t'],'orders'=>(new Order)->all(),'vendors'=>(new Vendor)->all(),'users'=>(new User)->all()]); } public function vendors(){return $this->view('admin/vendors',['vendors'=>(new Vendor)->all()]);} public function approveVendor(Request $r,int $id){(new Vendor)->update($id,['status'=>$r->get('status','approved')]); return $this->redirect('/admin/vendors');} public function reports(){header('Content-Type:text/csv'); header('Content-Disposition:attachment; filename=orders.csv'); $out=fopen('php://output','w'); fputcsv($out,['Order','Total','Status']); foreach((new Order)->all() as $o) fputcsv($out,[$o['number'],$o['total'],$o['status']]); return ''; } }
